#!/usr/bin/env python3
"""Generates ehal_css_gz.h (gzip byte array) from tools/ehal_css.h.src.
Usage:  python3 tools/gen_css_gz.py <src-dir>   (after every change to tools/ehal_css.h.src)"""
import gzip, re, sys, pathlib
src = pathlib.Path(sys.argv[1])
css = re.search(r'R"\((.*)\)"', (pathlib.Path(__file__).parent / "ehal_css.h.src").read_text(), re.S).group(1)
gz = gzip.compress(css.encode(), compresslevel=9, mtime=0)
rows = ',\n'.join('        ' + ','.join(f'0x{b:02x}' for b in gz[i:i+24]) for i in range(0, len(gz), 24))
(src / 'ehal_css_gz.h').write_text(f'''#pragma once
// GENERATED by tools/gen_css_gz.py from tools/ehal_css.h.src -- do not edit by hand.
// Original: {len(css)} B, gzip: {len(gz)} B

#include <Arduino.h>

namespace ehal
{{
    const size_t PAGE_CSS_GZ_LEN = {len(gz)};
    const uint8_t PAGE_CSS_GZ[] PROGMEM = {{
{rows}
    }};
}}
''')
print(f'CSS {len(css)} B -> gzip {len(gz)} B')
